 dict(kind='modules',tag='UNE EXPÉRIENCE COHÉRENTE',title='Six espaces.\nUn même fil conducteur.',lead='Retrouver les informations utiles et avancer naturellement d’une tâche à l’autre.',cards=[('01','Vue d’ensemble','Les commandes, les disponibilités et les points d’attention.'),('02','Clients','Les coordonnées et l’historique d’une relation.'),('03','Commandes','De la création à la confirmation de livraison.'),('04','Cave','Les lots, le vrac et les mouvements de démonstration.'),('05','Factures','Les échéances et le suivi des règlements fictifs.'),('06','Vins & stocks','Les références, les millésimes et les bouteilles disponibles.')],notes='Ces six espaces existent dans la maquette HTML. Montrer le fil conducteur plutôt qu’une simple liste de modules. La facture présentée est indicative et ne calcule pas la TVA.'),
