def para(s):return escape(s).replace('\n','<br>')
def picture(s):return f'<div class="screen-frame"><div class="window-bar"><i></i><i></i><i></i><span>Cuvée · aperçu de la maquette</span></div><img src="assets/{s["image"]}" alt="Capture réelle de la maquette : {escape(s["tag"])}" loading="eager"></div>'
def cardlist(s):return ''.join(f'<article class="card"><span class="card-no">{card[0]}</span><h3>{escape(card[1])}</h3><p>{escape(card[2])}</p>{f"<small>{escape(card[3])}</small>" if len(card)>3 else ""}</article>' for card in s['cards'])
def points(s):return '<div class="points">'+''.join(f'<div><span class="point-mark"></span><h3>{escape(a)}</h3><p>{escape(b)}</p></div>' for a,b in s['points'])+'</div>'
sections=[]
for i,s in enumerate(slides):
 h=f'<p class="eyebrow">{s["tag"]}</p><h1>{para(s["title"])}</h1><p class="lead">{para(s["lead"])}</p>'
 if s['kind']=='cover':body=f'<div class="cover-copy"><div class="wordmark">cuvée<span>.</span></div>{h}<span class="cover-tag">PROPOSITION CLIENT · 16 OCTOBRE 2026</span></div><div class="cover-visual">{picture(s)}<p>Du premier contact à la dernière bouteille.</p></div>'
 elif s['kind'] in ['screen','invoice']:body=f'<header>{h}</header><div class="product-grid {s["kind"]}">{picture(s)}{points(s)}</div>'
 elif s['kind']=='closing':body=f'<div class="closing-copy">{h}<a class="demo-button" href="../index.html" target="_blank" rel="noopener">Découvrir la maquette <span>↗</span></a></div><div class="closing-cards">{cardlist(s)}</div>'
 else:body=f'<header>{h}</header><div class="cards {s["kind"]}">{cardlist(s)}</div>'
 caption=f'<p class="caption">{escape(s["caption"])}</p>' if s.get('caption') else ''
 sections.append(f'<section class="slide {s["kind"]} {"active" if i==0 else ""}" data-title="{escape(s["title"].replace(chr(10)," "))}" aria-label="Diapositive {i+1} sur {len(slides)}" {"" if i==0 else "hidden"}>{body}{caption}<footer class="slide-footer"><span>Cuvée · présentation de projet</span><span>{i+1:02d} / {len(slides):02d}</span></footer></section>')
